    ("reticulum", "the fine network pattern on the stem of the porcini and some other boletes"),
    ("clavate", "describing a stem that is club-shaped, thicker at the base"),
    ("bulbous", "describing a stem base that is swollen like a bulb, typical of Amanitas"),
    ("mycelial cord", "a bundled strand of hyphae that transports nutrients through the soil"),
    ("rhizomorph", "a root-like strand of hyphae, such as the black cords of the honey fungus"),
    ("basidium", "the club-shaped spore-bearing cell of basidiomycetes"),
    ("ascus", "the sac-like spore-bearing cell of ascomycetes, containing eight spores in many species"),
    ("peridium", "the outer skin of a puffball or earthball"),
    ("gleba", "the spore-bearing interior tissue of puffballs, stinkhorns and truffles"),
    ("operculum", "the lid-like opening through which some ascomycetes discharge their spores"),
    ("hymenium", "the spore-bearing surface of a fungus, whether gills, pores, teeth or smooth flesh"),
    ("context", "the flesh of a mushroom cap, between the surface and the gills"),
    ("trama", "the internal tissue of the gills or cap"),
    ("cheilocystidia", "sterile cells on the edge of the gills, used in microscopic identification"),
    ("pileocystidia", "sterile cells on the surface of the cap, visible under a microscope"),
    ("spore ornamentation", "the surface texture of a spore, such as warts, spines or ridges, visible only under a microscope"),
